CREATE TABLE raw.cge_flood_points (
    id serial PRIMARY KEY,
    zone character varying(255) NOT NULL,
    neighborhood character varying(255) NOT NULL,
    initial_timestamp timestamp without time zone NOT NULL,
    final_timestamp timestamp without time zone NOT NULL,
    event_local character varying(255) NOT NULL,
    way character varying(255) NOT NULL,
    reference character varying(255) NOT NULL,
    coordinates public.geometry(Point,4326)
);

